pub fn t(s: &'static str) -> &'static str {
    try_t(s).unwrap_or(s)
}

pub fn t_shared(s: &SharedString) -> SharedString {
    if let Some(translated) = try_t(s.as_ref()) {
        SharedString::new_static(translated)
    } else {
        s.clone()
    }
}

